def find_digit(k):
    total = 0
    length = 1
    while total + length * (10**length - 10**(length-1)) < k:
        total += length * (10**length - 10**(length-1))
        length += 1

    k -= total
    num = 10**(length-1) + (k-1) // length
    return int(str(num)[(k-1) % length])

