def solve_sequence_queries():
    q = int(input())
    queries = [int(input()) for _ in range(q)]

    def find_digit(k):
        total = 0
        digits = 0
        i = 0
        while total < k:
            i += 1
            digits += 1
            total += i * 10 ** (digits - 1)

        k -= total - i * 10 ** (digits - 1)
        num = 10 ** (digits - 1) + (k - 1) // digits
        return int(str(num)[(k - 1) % digits])

    for k in queries:
        print(find_digit(k))
